begin;
insert into public.ce_course3_resources(id,data) values
('course3_module3_pdf','{"base64": "", "sha256": "4c855726ef9946a77cb8b3ce5c3b10cde578331a6c33107c18cd44fe4b1285d4", "filename": "CE_HALO_Course3_Module03_Documentation_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course3_module3_questions','[{"module_id": "course_3_module_3", "question_id": "course_3_module_3_q01", "question_number": 1, "stem": "The anesthesia record is best described legally as:", "choice_a": "A contemporaneous clinical account created close in time to the care and frequently the most reliable perioperative record in litigation, board, and credentialing review", "choice_b": "A summary written after the case for quality improvement", "choice_c": "An administrative billing form only", "choice_d": "An internal safety document that is not discoverable", "correct_choice": "a", "rationale": "Courts and reviewers treat the anesthesia record as the most reliable account of perioperative care because it is created contemporaneously. It is a clinical, billing, compliance, and — if needed — liability-defense document.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q02", "question_number": 2, "stem": "Under CMS 42 CFR §482.52 and Appendix A, the preanesthesia evaluation must be documented:", "choice_a": "Within 7 days of the procedure by any physician", "choice_b": "Within 48 hours before surgery or the procedure by an individual qualified to administer anesthesia", "choice_c": "At any time up to 30 days before the procedure", "choice_d": "Within 24 hours before the procedure by a registered nurse", "correct_choice": "b", "rationale": "42 CFR §482.52 and the CMS Appendix A Interpretive Guidelines require the preanesthesia evaluation to be performed and documented within 48 hours before surgery or the procedure by a qualified individual.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q03", "question_number": 3, "stem": "Under CMS requirements, the postanesthesia evaluation must be:", "choice_a": "Completed within 4 hours by the PACU RN", "choice_b": "Optional if the case is uncomplicated", "choice_c": "Completed no later than 48 hours after the procedure by a qualified individual, after the patient has recovered sufficiently to participate", "choice_d": "Completed during emergence in the OR", "correct_choice": "c", "rationale": "CMS requires the postanesthesia evaluation to be completed within 48 hours after surgery, by an individual qualified to administer anesthesia, and after the patient has recovered sufficiently to participate — not during immediate emergence.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q04", "question_number": 4, "stem": "Which format is most useful for documenting clinical judgment during an intraoperative event?", "choice_a": "\"Patient stable\"", "choice_b": "SBAR only", "choice_c": "Free-text summary written after the case", "choice_d": "Observation–Interpretation–Action–Response–Plan (OIARP)", "correct_choice": "d", "rationale": "OIARP (observation, interpretation, action, response, plan) captures both the clinical action and the judgment behind it — the elements malpractice reviewers most often find missing.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q05", "question_number": 5, "stem": "A CRNA discovers a factual documentation error two hours after the case. The correct action is to:", "choice_a": "Use the facility''s correction/addendum feature, clearly identify the correction, do not obscure the original, and document factually", "choice_b": "Ignore the error to avoid attracting attention", "choice_c": "Backdate the corrected entry to the original time", "choice_d": "Delete the original entry and re-enter the correct information", "correct_choice": "a", "rationale": "Corrections must be transparent, dated, timed, signed, and must not obscure the original record. Deletion or backdating is a serious violation and a well-recognized malpractice red flag.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q06", "question_number": 6, "stem": "Which of the following statements about EHR copy-forward is TRUE?", "choice_a": "Copy-forward eliminates the need to sign the note", "choice_b": "Findings should never be copy-forwarded unless the CRNA personally reassessed and confirmed them", "choice_c": "Copy-forward is always acceptable in anesthesia records", "choice_d": "Copy-forward is required by CMS for time savings", "correct_choice": "b", "rationale": "Copy-forward without personal reassessment produces outdated or false findings — one of the most common EHR-related documentation criticisms in malpractice review.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q07", "question_number": 7, "stem": "A patient exsanguinates during a case. Charting was impossible during active resuscitation. The CRNA completes the entry 90 minutes later. The correct approach is to:", "choice_a": "Backdate the entry to match the event time", "choice_b": "Ask a colleague to sign the entry", "choice_c": "Chart as \"late entry,\" note the time the entry is being made and the time the care occurred, and provide an objective factual timeline", "choice_d": "Skip documentation because it is too late", "correct_choice": "c", "rationale": "Late entries are expected in emergencies. They must be clearly identified, dated and timed at the time of entry, and must reference the time care occurred.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q08", "question_number": 8, "stem": "The medical record and the institutional incident report differ in that:", "choice_a": "Both should include speculation about fault", "choice_b": "The medical record and the incident report should be identical", "choice_c": "The incident report replaces the medical record in adverse events", "choice_d": "The medical record contains objective clinical facts; the incident report is an internal safety document — and the medical record should not state that an incident report was filed", "correct_choice": "d", "rationale": "The medical record is a clinical document; the incident report is an internal safety document. Referencing the incident report in the record can waive certain safety-review protections.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q09", "question_number": 9, "stem": "ASA Standards for Basic Anesthetic Monitoring (2020, reaffirmed 2025) require continuous evaluation of:", "choice_a": "Oxygenation, ventilation, circulation, and temperature during all anesthetics", "choice_b": "Only oxygenation and ventilation", "choice_c": "Only blood pressure and heart rate", "choice_d": "Only ECG", "correct_choice": "a", "rationale": "The ASA standards require continuous evaluation of oxygenation, ventilation, circulation, and temperature during all anesthetics.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q10", "question_number": 10, "stem": "Which of the following best reflects AANA Standard 14 (Documentation) when patient-specific circumstances require a deviation from usual practice?", "choice_a": "The deviation must not be documented", "choice_b": "The reason for the modification should be documented in the patient''s healthcare record", "choice_c": "The deviation is prohibited", "choice_d": "The deviation should be documented only in the incident report", "correct_choice": "b", "rationale": "AANA standards recognize that patient-specific circumstances may require modification of usual standards; when a standard is modified, the reason must be documented in the healthcare record.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q11", "question_number": 11, "stem": "A malpractice reviewer criticizes an anesthesia record that describes hypotension as \"BP low, treated, patient stable.\" The most defensible replacement note would:", "choice_a": "Add a note that an incident report was filed", "choice_b": "Delete the original entry", "choice_c": "Use the OIARP structure — objective vitals, interpretation, intervention with rationale, patient response with objective reassessment, and plan", "choice_d": "Say only \"anesthesia complications discussed with team\"", "correct_choice": "c", "rationale": "OIARP addresses the reviewer''s core criticism — that the record did not show recognition, decision-making, intervention, response, or plan.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q12", "question_number": 12, "stem": "A CRNA prints the electronic anesthesia record after a case. It shows an unresolved SpO₂ artifact from a probe malfunction that was not explained. In litigation, this is likely to be viewed as:", "choice_a": "Unremarkable, because artifacts are common", "choice_b": "Evidence of high quality of care", "choice_c": "A billing violation", "choice_d": "A gap that should have been explained in the narrative — unexplained artifacts and gaps are commonly criticized", "correct_choice": "d", "rationale": "Unresolved artifacts, unexplained gaps in monitoring, and missing times are commonly criticized. The CRNA should personalize templated text and explain clinically significant deviations or artifacts.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q13", "question_number": 13, "stem": "Which regulation establishes the Condition of Participation for hospital anesthesia services and is the source of the 48-hour preanesthesia and postanesthesia timing rules?", "choice_a": "42 CFR §482.52", "choice_b": "42 CFR §482.13", "choice_c": "42 CFR §482.51", "choice_d": "42 CFR §482.24", "correct_choice": "a", "rationale": "42 CFR §482.52 is the Condition of Participation for anesthesia services. It is the source of the preanesthesia (48 hours before), intraoperative, and postanesthesia (48 hours after) documentation requirements as applied by the CMS Appendix A Interpretive Guidelines.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q14", "question_number": 14, "stem": "A patient requests an amendment to the anesthesia record. The CRNA should:", "choice_a": "Ignore the request", "choice_b": "Route the request through the facility health-information-management process per HIPAA §164.526 and facility policy", "choice_c": "Rewrite the entry to match the patient''s version", "choice_d": "Immediately delete the disputed entry", "correct_choice": "b", "rationale": "Patient-requested amendments are handled through the facility HIM process per HIPAA §164.526. The CRNA should not unilaterally alter the record in response to a patient request.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q15", "question_number": 15, "stem": "Which of the following NPDB statements is TRUE?", "choice_a": "The NPDB is a state repository maintained by boards of nursing", "choice_b": "Only physicians are reportable to the NPDB", "choice_c": "The NPDB is a federal repository for medical malpractice payments and certain adverse actions involving healthcare practitioners, including adverse licensure and clinical privileges actions of specified duration", "choice_d": "The NPDB includes only criminal convictions", "correct_choice": "c", "rationale": "The NPDB is a federal repository administered by HRSA. It captures malpractice payments and adverse licensure, certification, and clinical-privileges actions as defined in the NPDB Guidebook.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q16", "question_number": 16, "stem": "During a difficult intubation, defensible documentation should include all of the following EXCEPT:", "choice_a": "Number of attempts and the device used per attempt", "choice_b": "Oxygenation status between attempts", "choice_c": "Notification of help and rescue devices used", "choice_d": "Blame directed at the surgeon for causing the difficult intubation", "correct_choice": "d", "rationale": "The record should be objective and clinical. Blaming colleagues is inappropriate and damaging in litigation. Documentation should describe attempts, devices, oxygenation, help notification, and rescue actions.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q17", "question_number": 17, "stem": "A CRNA transfers care to a colleague for a break. AANA Standard 12 (Transfer of Responsibility for Care) requires documentation that includes:", "choice_a": "The time, receiving clinician, key events, current medications/infusions, outstanding orders, and any acute concerns", "choice_b": "A statement that \"no issues\" occurred", "choice_c": "Only the receiving clinician''s name", "choice_d": "Only the time of relief", "correct_choice": "a", "rationale": "AANA Standard 12 requires communication of information necessary for continued patient care and documentation of the transfer of responsibility — including time, receiving clinician, and clinically relevant information.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q18", "question_number": 18, "stem": "The 21st Century Cures Act and ONC information-blocking rule generally require:", "choice_a": "Charging patients to view their notes", "choice_b": "Prompt patient electronic access to their notes, including anesthesia notes", "choice_c": "Deleting anesthesia notes older than 7 years", "choice_d": "Restricting patient access to anesthesia notes", "correct_choice": "b", "rationale": "The 21st Century Cures Act and ONC final rule generally require prompt patient electronic access to notes. CRNAs should continue to chart honestly and clinically, while avoiding unnecessarily judgmental language.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q19", "question_number": 19, "stem": "A CRNA is asked to sign a preanesthesia note in the EHR that contains contradictory allergy entries. The correct action is to:", "choice_a": "Add a comment stating that the record is unreliable", "choice_b": "Delete both entries", "choice_c": "Reconcile the contradiction before signing", "choice_d": "Sign the note and address the contradiction later", "correct_choice": "c", "rationale": "Contradictions within the same record are a frequent reviewer criticism and can be materially harmful in litigation. The CRNA should reconcile contradictions before signing.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q20", "question_number": 20, "stem": "Which of the following is a required element of the postanesthesia evaluation under CMS requirements?", "choice_a": "Anesthesia billing codes", "choice_b": "Discharge medication reconciliation only", "choice_c": "The patient''s satisfaction score", "choice_d": "Respiratory function, cardiovascular function, mental status, temperature, pain, nausea/vomiting, and hydration", "correct_choice": "d", "rationale": "CMS Appendix A specifies the required content of the postanesthesia evaluation, including respiratory, cardiovascular, mental status, temperature, pain, nausea/vomiting, and hydration.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q21", "question_number": 21, "stem": "A high-risk preanesthesia finding (e.g., OSA, difficult airway) is documented without a corresponding plan. This is:", "choice_a": "A common malpractice-review concern — high-risk findings should be tied to a specific plan (e.g., video laryngoscopy, awake fiberoptic contingency, postoperative CPAP, monitored bed)", "choice_b": "Compliant with AANA standards", "choice_c": "Best practice to avoid pre-committing to a plan", "choice_d": "Only a billing issue", "correct_choice": "a", "rationale": "Naming a high-risk finding without a specific plan is a well-recognized documentation weakness. Reviewers expect the record to tie findings to action.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q22", "question_number": 22, "stem": "An anesthesia record that has been altered after an adverse event in a way that could be interpreted as concealment is considered:", "choice_a": "Acceptable as long as the CRNA signs it", "choice_b": "One of the most damaging fact patterns in malpractice litigation and independently sanctionable by boards", "choice_c": "Best practice for risk management", "choice_d": "Standard workflow", "correct_choice": "b", "rationale": "Alteration after an adverse event is one of the most damaging fact patterns in litigation and can trigger board action independent of the underlying clinical care.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q23", "question_number": 23, "stem": "An anesthesia record contains automated device data that conflicts with the CRNA''s narrative note. In review, this typically requires:", "choice_a": "Deleting the conflicting device data", "choice_b": "Ignoring the conflict", "choice_c": "A narrative explanation of the artifact, device malfunction, or intervention that reconciles the two data sources", "choice_d": "Blaming the EHR vendor", "correct_choice": "c", "rationale": "Automated data should be interpreted, not deleted. The narrative should reconcile conflicting data sources — explaining artifacts, device issues, or interventions.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q24", "question_number": 24, "stem": "Which framework is most likely to be cited by a court or expert reviewer as evidence of accepted anesthesia documentation and monitoring expectations for CRNAs?", "choice_a": "Only the CRNA''s personal preferences", "choice_b": "Only the surgeon''s operative note", "choice_c": "Only the incident report", "choice_d": "AANA Standards for Nurse Anesthesia Practice (2019), ASA Statement on Documentation of Anesthesia Care (2024), CMS 42 CFR §482.52, and The Joint Commission RC.02.01.01 and RC.01.03.01 — used together", "correct_choice": "d", "rationale": "Reviewers rely on the combined weight of AANA, ASA, CMS, and Joint Commission requirements — as well as state law and facility policy — to define accepted documentation practice.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_3", "question_id": "course_3_module_3_q25", "question_number": 25, "stem": "Which of the following is the single most valuable long-term risk-management tool available to the CRNA?", "choice_a": "An anesthesia record that is accurate, timely, complete, internally consistent, individualized, and demonstrates clinical judgment", "choice_b": "Silence about clinical events", "choice_c": "A brief record with only vital signs", "choice_d": "A record that omits complications to avoid liability", "correct_choice": "a", "rationale": "An accurate, timely, complete, individualized, and internally consistent record that also demonstrates clinical judgment is the most durable long-term risk-management tool available to the CRNA.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
do $$ begin
assert (select encode(sha256(decode(data->>'base64','base64')),'hex')=data->>'sha256' from public.ce_course3_resources where id='course3_module3_pdf'),'PDF hash mismatch';
assert (select released=false from public.ce_course3_catalog where id='1047243'),'Course must remain staged';
end $$;
commit;